using System;using System.Linq;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;
namespace Touchfish {public partial class PanelWindow {
 bool lanSealedMode;SealedSession sealedSession;SealedView sealedView;Grid sealedStage;int sealedPendingRevision=-1;DateTime sealedRebuildAt=DateTime.MaxValue;
 bool SealedInputReady{get{return !lanWaiting&&(!lanMode||lanPeer!=null&&lanPeer.IsConnected);}}
 bool SealedModeSelected(){return lanModePicker!=null&&lanModePicker.SelectedItem!=null&&((Choice)lanModePicker.SelectedItem).Key=="sealed";}
 void BuildSealedStage(Grid parent){sealedStage=new Grid{Visibility=Visibility.Collapsed};parent.Children.Add(sealedStage);}
 void ResetSealed(){lanSealedMode=false;sealedSession=null;sealedView=null;sealedPendingRevision=-1;sealedRebuildAt=DateTime.MaxValue;if(sealedStage!=null)sealedStage.Visibility=Visibility.Collapsed;}
 string SealedScore(){return sealedView==null?"现开赛":sealedView.Wins0+" - "+sealedView.Wins1+" · 第 "+sealedView.Round+" 局";}
 void StartSealed(string opponent,EffectLevel effects){lanGuestName=PlayerNames.Normalize(opponent,1);lanGuestEffects=effects;sealedSession=new SealedSession(catalog,Environment.TickCount,matchRules.Supports);PublishSealed();}
 void PublishSealed(string error=null){sealedView=sealedSession.View(0);RenderSealed();if(lanPeer!=null&&!lanPeer.Send(new LanMessage{Kind="sealed-view",Sealed=sealedSession.View(1),Message=error}))DisconnectLan("现开状态发送失败。");}
 void SealedAction(string kind,string id=null,int amount=0){if(!lanSealedMode||sealedView==null||!SealedInputReady)return;if(lanIsHost){try{sealedSession.Act(0,sealedView.Session,sealedView.Revision,kind,id,amount);if(sealedSession.Ready){StartSealedMatch();return;}PublishSealed();}catch(InvalidOperationException ex){status.Text=ex.Message;}catch(System.IO.InvalidDataException ex){status.Text=ex.Message;}}else{sealedPendingRevision=sealedView.Revision;lanWaiting=true;RenderSealed();if(lanPeer==null||!lanPeer.Send(new LanMessage{Kind="sealed-action",ArenaSession=sealedView.Session,ArenaRevision=sealedView.Revision,SealedAction=kind,SealedCard=id,SealedAmount=amount}))DisconnectLan("现开操作发送失败。");}}
 bool ReceiveSealed(LanMessage message){if(!lanSealedMode)return false;if(lanIsHost&&message.Kind=="sealed-action"){if(sealedSession==null||lanReady)return true;try{sealedSession.Act(1,message.ArenaSession,message.ArenaRevision,message.SealedAction,message.SealedCard,message.SealedAmount);if(sealedSession.Ready){StartSealedMatch();return true;}PublishSealed();}catch(Exception ex){if(!(ex is InvalidOperationException||ex is System.IO.InvalidDataException))throw;lanPeer.Send(new LanMessage{Kind="sealed-view",Sealed=sealedSession.View(1),Message=ex.Message});}return true;}
  if(!lanIsHost&&message.Kind=="sealed-view"){var view=message.Sealed;if(view==null||String.IsNullOrEmpty(view.Session)||sealedView!=null&&view.Session!=sealedView.Session)throw new System.IO.InvalidDataException("现开房间标识无效。");if(sealedView!=null&&view.Revision<sealedView.Revision)return true;if(lanReady&&view.Round<=sealedView.Round)return true;sealedView=view;lanReady=false;if(!lanWaiting||view.Revision>sealedPendingRevision||!String.IsNullOrEmpty(message.Message)){lanWaiting=false;sealedPendingRevision=-1;}RenderSealed();if(!String.IsNullOrEmpty(message.Message))status.Text=message.Message;return true;}return false;
 }
 void RenderSealed(bool navigate=true){if(sealedStage==null||sealedView==null)return;sealedStage.Height=minimal?170:300;SetArenaDraftLayout(true);lanNotice.Visibility=Visibility.Collapsed;arenaStage.Visibility=Visibility.Collapsed;sealedStage.Visibility=Visibility.Visible;sealedStage.Children.Clear();sealedStage.RowDefinitions.Clear();foreach(double h in new[]{22.0,24.0,-1.0,24.0})sealedStage.RowDefinitions.Add(new RowDefinition{Height=h<0?new GridLength(1,GridUnitType.Star):new GridLength(h)});
  sealedStage.Children.Add(T("现开赛"+(sealedView.ClassId==null?"":" · "+ArenaClassLabel(sealedView.ClassId))+" · "+SealedScore(),10,Ink));var hint=T(sealedView.Phase=="class"?"选择职业，再开18包（90张）":sealedView.Phase=="open"?"已开 "+sealedView.Opened+" / 18 包":"卡组 "+sealedView.Deck.Values.Sum()+" / 30 · 对手"+(sealedView.OpponentConfirmed?"已确认":"正在准备"),9,Muted);Put(sealedStage,hint,1);
  if(sealedView.Phase=="class"){var options=new StackPanel();foreach(var choice in sealedView.Classes){string id=choice;var b=Btn(ArenaClassLabel(id),110);b.Height=26;b.Margin=new Thickness(0,3,0,3);b.IsEnabled=SealedInputReady;b.Click+=(s,e)=>SealedAction("class",id);options.Children.Add(b);}Put(sealedStage,options,2);}
  else if(sealedView.Phase=="open"){var opened=new StackPanel();foreach(var entry in sealedView.LastPack){var card=catalog.Card(entry.Id);var label=T(card.Cost+" · "+card.Name+" · "+RarityLabel(card.Rarity)+(entry.Quality=="golden"?" · 金色":""),10,Ink);label.ToolTip=card.Text;opened.Children.Add(label);}if(sealedView.LastPack.Length==0)opened.Children.Add(T("每包5张，至少一张稀有及以上。",10,Muted));Put(sealedStage,new ScrollViewer{Content=opened,VerticalScrollBarVisibility=ScrollBarVisibility.Auto},2);var buttons=new StackPanel{Orientation=Orientation.Horizontal};foreach(string action in new[]{"open","open-all"}){string kind=action;var b=Btn(kind=="open"?"开下一包":"全部打开",80);b.Height=22;b.IsEnabled=SealedInputReady;b.Click+=(s,e)=>SealedAction(kind);buttons.Children.Add(b);}Put(sealedStage,buttons,3);}
  else{var columns=new Grid();columns.ColumnDefinitions.Add(new ColumnDefinition());columns.ColumnDefinitions.Add(new ColumnDefinition());for(int side=0;side<2;side++){bool selected=side==1;var rows=new StackPanel();rows.Children.Add(T(selected?"已选卡组":"可用牌 · 剩余张数",9,Muted));var entries=(selected?sealedView.Deck:sealedView.Pool).OrderBy(p=>catalog.Card(p.Key).Cost).ThenBy(p=>catalog.Card(p.Key).Name);foreach(var pair in entries){string id=pair.Key;var card=catalog.Card(id);int count;sealedView.Deck.TryGetValue(id,out count);var row=new Grid{Height=22,Margin=new Thickness(0,0,3,0)};row.ColumnDefinitions.Add(new ColumnDefinition());row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(22)});var label=T(card.Cost+" "+card.Name+" ×"+(selected?pair.Value:pair.Value-count),9,Ink);label.TextTrimming=TextTrimming.CharacterEllipsis;label.ToolTip=card.Cost+"费 · "+card.Name+" · "+(card.Type=="MINION"?card.Attack+"/"+card.Health:card.Type=="WEAPON"?card.Attack+"/"+card.Durability:"法术")+" · "+card.Text;row.Children.Add(label);var b=Btn(selected?"−":"+",20);b.Height=20;b.Padding=new Thickness(0);b.IsEnabled=SealedInputReady&&!sealedView.Confirmed&&(selected||count<pair.Value&&sealedView.Deck.Values.Sum()<30);int delta=selected?-1:1;b.Click+=(s,e)=>SealedAction("edit",id,delta);Grid.SetColumn(b,1);row.Children.Add(b);rows.Children.Add(row);}var scroll=new ScrollViewer{Content=rows,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};Grid.SetColumn(scroll,side);columns.Children.Add(scroll);}Put(sealedStage,columns,2);var confirm=Btn(sealedView.Confirmed?"已确认 · 等待对方":"确认30张卡组",140);confirm.Height=22;confirm.IsEnabled=SealedInputReady&&!sealedView.Confirmed&&sealedView.Deck.Values.Sum()==30;confirm.Click+=(s,e)=>SealedAction("confirm");Put(sealedStage,confirm,3);}
  ApplyFonts(sealedStage);if(navigate)ShowPage("lan");status.Text=lanWaiting?"等待现开状态确认。":"现开赛 · 仅能使用本次开出的牌；局间可重组。";
 }
 void HideSealed(){if(sealedStage!=null)sealedStage.Visibility=Visibility.Collapsed;SetArenaDraftLayout(false);lanNotice.Visibility=Visibility.Visible;}
 void StartSealedMatch(){lanAuthority=new LanHostGame(catalog,sealedSession.Deck(0),sealedSession.Deck(1),Environment.TickCount,hostName:lanChosenName,guestName:lanGuestName,mode:GameModes.Sealed);lanAuthority.SetPresentation(0,CurrentEffects);lanAuthority.SetPresentation(1,lanGuestEffects);sealedView=sealedSession.View(0);match=lanAuthority.Game;lanSession=lanAuthority.Session;lanRevision=0;lanReady=true;lanWaiting=false;matchViewSeat=0;awaitHandoff=false;ClearPending();selectedMulligan.Clear();inspectMatch=false;matchHandScroll=0;HideSealed();PublishLan();RenderMatch();ShowPage("match");}
 void StampSealed(LanMessage message){if(!lanSealedMode||sealedSession==null)return;message.State.ArenaWins0=lanArenaWins0=sealedSession.Wins0;message.State.ArenaWins1=lanArenaWins1=sealedSession.Wins1;message.State.ArenaGameNumber=lanArenaGameNumber=sealedSession.Round;message.State.ArenaSeriesWinner=lanArenaSeriesWinner=sealedSession.SeriesWinner;}
 bool TickSealed(){if(!lanSealedMode||!lanIsHost||!lanReady||sealedSession==null||match==null||!match.Finished||match.AnimationPlaying)return false;if(!sealedSession.ResultRecorded){sealedSession.RecordResult(match.Winner);sealedView=sealedSession.View(0);PublishLan();RenderMatch();sealedRebuildAt=DateTime.UtcNow.AddMilliseconds(1800);}if(sealedSession.SeriesWinner==-2&&DateTime.UtcNow>=sealedRebuildAt){sealedSession.BeginRebuild();lanReady=false;lanWaiting=false;PublishSealed();}return true;}
}}
